using System.IO;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class B3RestoreImporter {public static object Run(){string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));int count=0;foreach(var q in JArray.Parse(File.ReadAllText(r+"/SourceAssets/B3_FullFloor/restore_texture_settings.json"))){var t=(TextureImporter)AssetImporter.GetAtPath((string)q["path"]);t.textureType=(TextureImporterType)(int)q["textureType"];t.sRGBTexture=(int)q["sRGBTexture"]==1;t.anisoLevel=(int)q["aniso"];t.wrapModeU=(TextureWrapMode)(int)q["wrapU"];t.wrapModeV=(TextureWrapMode)(int)q["wrapV"];t.wrapModeW=(TextureWrapMode)(int)q["wrapW"];t.maxTextureSize=(int)q["maxTextureSize"];t.textureCompression=(TextureImporterCompression)(int)q["textureCompression"];t.SaveAndReimport();count++;}return new{restored=count};}}
